/* ============================================
   ПЛАВНЫЙ HOVER БЕЗ «МОРГАНИЯ»
   Причина мигания: transform (сдвиг) на :hover поднимает элемент
   на отдельный GPU-слой, который в конце обратной анимации
   разрушается — на один кадр элемент «пропадает». Особенно остро
   с overflow:hidden + border-radius (баг отрисовки скруглённого слоя).
   Решение: на :hover НЕ двигаем элемент (transform убран полностью),
   обратная связь — мягкая тень и рамка. Переходы плавные (ease-out)
   и быстрые (~0.24s), без резких остановок.
   ============================================ */
.subject-card,
.nav-link, .task-card, .stat-card,
.definition-box, .formula-box, .remark-box, .reminder-box, .experiment-box, .derivation-box,
.theorem-box, .lemma-box, .example-box, .statement-box, .corollary-box,
.proof-box, .properties-box {
    transition: box-shadow 0.24s cubic-bezier(0.33, 1, 0.68, 1),
                border-color 0.24s cubic-bezier(0.33, 1, 0.68, 1),
                background-color 0.24s cubic-bezier(0.33, 1, 0.68, 1),
                color 0.24s cubic-bezier(0.33, 1, 0.68, 1) !important;
}
body:not(.no-hover) .subject-card:hover,
body:not(.no-hover) .nav-link:hover,
body:not(.no-hover) .task-card:hover,
body:not(.no-hover) .stat-card:hover,
body:not(.no-hover) .toggle-derivation:hover,
body:not(.no-hover) .toggle-proof:hover,
body:not(.no-hover) .definition-box:hover,
body:not(.no-hover) .formula-box:hover,
body:not(.no-hover) .remark-box:hover,
body:not(.no-hover) .reminder-box:hover,
body:not(.no-hover) .experiment-box:hover,
body:not(.no-hover) .derivation-box:hover,
body:not(.no-hover) .theorem-box:hover,
body:not(.no-hover) .lemma-box:hover,
body:not(.no-hover) .example-box:hover,
body:not(.no-hover) .statement-box:hover,
body:not(.no-hover) .corollary-box:hover,
body:not(.no-hover) .proof-box:hover,
body:not(.no-hover) .properties-box:hover {
    transform: none !important;
}

body {
    font-family: var(--font-sans, 'Onest', 'Segoe UI Variable Text', 'Segoe UI',
        -apple-system, BlinkMacSystemFont, 'Helvetica Neue', Arial, sans-serif);
    background-color: var(--bg-primary);
    color: var(--text-primary);
    line-height: 1.8;
    overflow-x: hidden;
    transition: background-color 0.15s ease,
                color 0.15s ease;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    letter-spacing: 0.01em;
}

/* РџСЂРµРґРѕС‚РІСЂР°С‰РµРЅРёРµ РїСЂРѕРєСЂСѓС‚РєРё body РєРѕРіРґР° sidebar РѕС‚РєСЂС‹С‚ РЅР° РјРѕР±РёР»СЊРЅС‹С… */
body.sidebar-open,
body.modal-open {
    overflow: hidden;
}

/* Когда открыта модалка настроек — прячем плавающие кнопки (режим заучивания,
   стрелка вверх, FAB-кнопки), иначе они просвечивают поверх затемнения. */
body.modal-open .study-mode-toggle,
body.modal-open .scroll-to-top,
body.modal-open .menu-toggle,
body.modal-open .settings-button {
    visibility: hidden !important;
}

/* Дополнительно фиксируем body на мобильных, чтобы фон под модалкой не скроллился
   при свайпе на iOS — overflow: hidden один не справляется. */
@media (max-width: 768px) {
    body.modal-open {
        position: fixed;
        inset: 0;
        width: 100%;
    }
}

/* РћРІРµСЂР»РµР№ РґР»СЏ sidebar РЅР° РјРѕР±РёР»СЊРЅС‹С… */
.sidebar-overlay {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    height: 100dvh;
    background: rgba(0, 0, 0, 0.5);
    z-index: 999;
    opacity: 0;
    transition: opacity 0.3s ease;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
}

.sidebar-overlay.active {
    display: block;
    opacity: 1;
}


/* ============================================
   Р‘РћРљРћР’РђРЇ РџРђРќР•Р›Р¬ РќРђР’РР“РђР¦РР
   ============================================ */

.sidebar {
    position: fixed;
    left: 0;
    top: 0;
    width: var(--sidebar-width);
    height: 100vh;
    height: 100dvh;
    background: var(--bg-secondary);
    border-right: 1px solid var(--border-color);
    overflow-y: auto;
    z-index: 1000;
    transition: transform 0.4s cubic-bezier(0.4, 0, 0.2, 1),
                width 0.3s cubic-bezier(0.4, 0, 0.2, 1),
                background-color 0.15s ease,
                border-color 0.15s ease;
    box-shadow: var(--shadow-xl);
    display: flex;
    flex-direction: column;
    backdrop-filter: blur(10px);
}

.sidebar::-webkit-scrollbar {
    width: 8px;
}

.sidebar::-webkit-scrollbar-track {
    background: var(--bg-tertiary);
}

.sidebar::-webkit-scrollbar-thumb {
    background: var(--accent-color);
    border-radius: 4px;
}

.sidebar-header {
    padding: var(--spacing);
    background: var(--header-bg);
    color: var(--header-text);
    border-bottom: 1px solid transparent;
    position: sticky;
    top: 0;
    z-index: 10;
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 1rem;
    box-shadow: var(--shadow-sm);
    transition: background-color 0.3s ease, border-color 0.3s ease;
}

body.dark-theme .sidebar-header {
    box-shadow: 0 4px 16px rgba(var(--accent-rgb), 0.25);
}

.sidebar-header h2 {
    font-size: 1.4rem;
    font-weight: 600;
    flex: 1 1 auto;
    min-width: 0;
}

.sidebar-header h2 a {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
}

.home-icon {
    width: 22px;
    height: 22px;
    flex-shrink: 0;
}

/* РљРѕРЅС‚РµР№РЅРµСЂ РґР»СЏ РєРЅРѕРїРѕРє РІ header */
.sidebar-header-buttons {
    display: flex;
    gap: 0.5rem;
    align-items: center;
    flex-shrink: 0;
}

.close-sidebar {
    display: none;
    background: var(--bg-tertiary);
    border: none;
    color: var(--text-secondary);
    width: 32px;
    height: 32px;
    border-radius: 50%;
    cursor: pointer;
    font-size: 1.2rem;
    transition: var(--transition);
    flex-shrink: 0;
}

.close-sidebar:hover {
    background: var(--border-color);
    color: var(--text-primary);
    transform: rotate(90deg);
}

body.dark-theme .close-sidebar {
    background: rgba(255, 255, 255, 0.2);
    color: white;
}

body.dark-theme .close-sidebar:hover {
    background: rgba(255, 255, 255, 0.3);
    color: white;
}

/* РџРѕРёСЃРє */
.search-box {
    padding: 1rem var(--spacing);
    background: var(--bg-tertiary);
    border-bottom: 1px solid var(--border-color);
    position: relative;
}

.search-box .sidebar-search-icon {
    position: absolute;
    left: calc(var(--spacing) + 0.7rem);
    top: 50%;
    transform: translateY(-50%);
    width: 16px;
    height: 16px;
    color: var(--text-secondary);
    pointer-events: none;
}

.search-box input {
    width: 100%;
    padding: 0.75rem 1rem 0.75rem 2.35rem;
    border: 1px solid var(--border-color);
    border-radius: 8px;
    background: var(--bg-primary);
    color: var(--text-primary);
    font-size: 0.95rem;
    transition: var(--transition);
}

.search-box input:focus {
    outline: none;
    border-color: var(--text-secondary);
    box-shadow: 0 0 0 3px rgba(15, 23, 42, 0.08);
}

body.dark-theme .search-box input:focus {
    box-shadow: 0 0 0 3px rgba(241, 245, 249, 0.1);
}

/* Разделы, опубликованные через конструктор, используют те же учебные блоки,
   что и ручная разметка. Эти правила отвечают только за вложенность и медиа. */
.constructor-content-section .constructor-nested-content {
    display: grid;
    gap: 0.85rem;
    margin-top: 0.9rem;
    padding-left: clamp(0.75rem, 2vw, 1.2rem);
    border-left: 1px solid var(--border-color);
}

.constructor-content-section .constructor-note-image {
    width: 100%;
    margin: 1.35rem 0;
    text-align: center;
}

.constructor-content-section .constructor-note-image img {
    display: block;
    width: auto;
    max-width: 100%;
    max-height: min(70vh, 720px);
    margin: 0 auto;
    border-radius: 10px;
}

.constructor-content-section .constructor-note-image figcaption {
    max-width: 68ch;
    margin: 0.55rem auto 0;
    color: var(--text-secondary);
    font-size: 0.86rem;
    line-height: 1.5;
}

/* Многопанельные физические схемы сохраняют читаемый масштаб подписей. */
.constructor-content-section :is(
    [data-note-block="boyle-mariotte-experiment-image"],
    [data-note-block="isothermal-process-graphs-image"],
    [data-note-block="isobaric-process-graphs-image"],
    [data-note-block="isobaric-coordinate-graphs-image"],
    [data-note-block="charles-experiment-image"],
    [data-note-block="combined-gas-law-image"],
    [data-note-block="intermolecular-interaction-image"]
) img {
    width: min(100%, 720px);
    height: auto;
    max-height: none;
}

.constructor-content-section [data-note-block="student-coefficients-image"] {
    overflow-x: auto;
    overscroll-behavior-inline: contain;
    scrollbar-width: thin;
}

.constructor-content-section [data-note-block="student-coefficients-image"] img {
    min-width: 650px;
    max-width: none;
}

.constructor-content-section .constructor-note-list {
    padding-left: 1.35rem;
}

.constructor-content-section .constructor-subsection + .constructor-subsection {
    margin-top: clamp(1.4rem, 3vw, 2.2rem);
}

.search-results-panel {
    flex: 0 0 auto;
    max-height: min(54vh, 520px);
    overflow: hidden;
    background: var(--bg-secondary);
    border-bottom: 1px solid var(--border-color);
    box-shadow: 0 10px 22px rgba(15, 23, 42, 0.08);
}

.search-results-panel.hidden { display: none; }

.search-results-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.6rem;
    min-height: 38px;
    padding: 0.45rem var(--spacing) 0.35rem;
    color: var(--text-secondary);
}

.search-results-head strong {
    font-size: 0.74rem;
    font-weight: 700;
    letter-spacing: 0.035em;
    text-transform: uppercase;
}

.search-results-close {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 30px;
    height: 30px;
    padding: 0;
    color: var(--text-secondary);
    background: transparent;
    border: 0;
    border-radius: 8px;
    cursor: pointer;
}

.search-results-close:hover { color: var(--text-primary); background: var(--bg-tertiary); }

.search-results-list {
    max-height: calc(min(54vh, 520px) - 38px);
    padding: 0 0.55rem 0.65rem;
    overflow-y: auto;
    overscroll-behavior: contain;
}

.site-search-scope {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0.24rem;
    margin: 0 0.55rem 0.48rem;
    padding: 0.22rem;
    background: var(--bg-tertiary);
    border: 1px solid var(--border-color);
    border-radius: 9px;
}

.site-search-panel .search-results-list {
    max-height: calc(min(54vh, 520px) - 82px);
}

.site-search-scope button {
    min-height: 30px;
    padding: 0.28rem 0.45rem;
    color: var(--text-secondary);
    background: transparent;
    border: 0;
    border-radius: 6px;
    font: inherit;
    font-size: 0.72rem;
    font-weight: 650;
    cursor: pointer;
}

.site-search-scope button.active {
    color: var(--text-primary);
    background: var(--bg-secondary);
    box-shadow: 0 1px 4px rgba(15, 23, 42, 0.08);
}

.site-search-empty {
    padding: 0.85rem 0.7rem 1rem;
    color: var(--text-secondary);
    font-size: 0.78rem;
    line-height: 1.45;
    text-align: center;
}

.search-result-item {
    display: flex;
    flex-direction: column;
    gap: 0.32rem;
    width: 100%;
    margin: 0;
    padding: 0.68rem 0.72rem;
    color: var(--text-primary);
    text-align: left;
    background: transparent;
    border: 1px solid transparent;
    border-radius: 10px;
    cursor: pointer;
}

.search-result-item + .search-result-item { margin-top: 0.18rem; }
.search-result-item:hover,
.search-result-item.active {
    background: var(--bg-tertiary);
    border-color: var(--border-color);
}

.search-result-item.active { border-color: var(--accent-color); }

.search-result-meta {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 0.6rem;
}

.search-result-meta strong {
    min-width: 0;
    overflow: hidden;
    font-size: 0.8rem;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.search-result-meta small {
    flex: 0 0 auto;
    color: var(--text-secondary);
    font-size: 0.66rem;
}

.search-result-snippet {
    display: -webkit-box;
    overflow: hidden;
    color: var(--text-secondary);
    font-size: 0.74rem;
    line-height: 1.38;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
}

mark.search-result-term {
    padding: 0 0.08em;
    color: inherit;
    background: rgba(250, 204, 21, 0.38);
    border-radius: 3px;
}

.search-target-pulse {
    animation: searchTargetPulse 1.05s ease-out;
}

@keyframes searchTargetPulse {
    0%, 100% { outline-color: transparent; outline-offset: 1px; }
    35% { outline: 4px solid rgba(var(--accent-rgb, 37, 99, 235), 0.2); outline-offset: 3px; }
}

.sidebar-actions {
    display: flex;
    gap: 0.5rem;
    padding: 0.5rem var(--spacing);
    border-bottom: 1px solid var(--border-color);
}

.sidebar-actions .knowledge-check-btn {
    flex: 1;
    margin: 0;
}

/* РќР°РІРёРіР°С†РёРѕРЅРЅРѕРµ РјРµРЅСЋ */
.nav-menu {
    padding: 1rem 0;
    display: flex;
    flex-direction: column;
    height: 100%;
}

.nav-section {
    margin-bottom: 1.5rem;
}

.nav-section h3 {
    padding: 0.5rem var(--spacing);
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--text-secondary);
    font-weight: 600;
}

.nav-section ul {
    list-style: none;
}

.nav-link {
    display: block;
    padding: 0.85rem var(--spacing);
    color: var(--text-primary);
    text-decoration: none;
    transition: var(--transition);
    border-left: 3px solid transparent;
    font-size: 0.95rem;
    border-radius: 0 var(--border-radius-sm) var(--border-radius-sm) 0;
    margin: 0.15rem 0;
}

.nav-link:hover {
    background: var(--bg-tertiary);
    border-left-color: var(--text-secondary);
    box-shadow: var(--shadow-sm);
}

.nav-link.active {
    background: var(--bg-tertiary);
    border-left-color: var(--text-secondary);
    color: var(--text-primary);
    font-weight: 600;
    box-shadow: var(--shadow-sm);
}

/* Р Р°СЃРєСЂС‹РІР°СЋС‰РёРµСЃСЏ РіСЂСѓРїРїС‹ РІ РЅР°РІРёРіР°С†РёРё */
.nav-group {
    margin: 0.5rem 0;
}

.nav-group-toggle {
    width: 100%;
    padding: 0.75rem var(--spacing);
    background: var(--bg-tertiary);
    border: none;
    border-left: 3px solid transparent;
    color: var(--text-primary);
    font-size: 0.95rem;
    font-weight: 600;
    text-align: left;
    cursor: pointer;
    transition: var(--transition);
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.nav-group-toggle:hover {
    background: var(--bg-primary);
    border-left-color: var(--text-secondary);
}

.nav-group-toggle .toggle-icon {
    font-size: 0.7rem;
    transition: transform 0.3s ease;
    display: inline-block;
}

.nav-group.open .toggle-icon {
    transform: rotate(-90deg);
}

.nav-submenu {
    list-style: none;
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.4s ease-out;
    background: var(--bg-primary);
    padding: 0;
}

.nav-group.open .nav-submenu {
    max-height: 2000px;
}

.nav-submenu .nav-link {
    padding-left: calc(var(--spacing) + 1rem);
    font-size: 0.9rem;
}

/* Подменю при наведении не сдвигается (раньше +0.5rem отступ выглядел как
   слишком резкий «прыжок»); подсветка — фоном из .nav-link:hover. */
.nav-submenu .nav-link:hover {
    padding-left: calc(var(--spacing) + 1rem);
}

/* Компактное оглавление: группы раскрыты при загрузке и могут сворачиваться. */
.nav-group {
    margin: 0.7rem 0 0.85rem;
}

.nav-group-toggle,
.nav-group-heading {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    width: 100%;
    padding: 0.38rem var(--spacing) 0.48rem;
    color: var(--text-secondary);
    background: transparent;
    border: 0;
    font-size: 0.76rem;
    font-weight: 700;
    line-height: 1.25;
    letter-spacing: 0.055em;
    text-align: left;
    text-transform: uppercase;
    cursor: pointer;
    transition: color 0.15s ease, background-color 0.15s ease;
}

.nav-group-toggle::before,
.nav-group-heading::before {
    content: '';
    width: 0.34rem;
    height: 0.34rem;
    flex: 0 0 auto;
    border-radius: 50%;
    background: currentColor;
    opacity: 0.5;
}

.nav-group-toggle .toggle-icon {
    display: inline-grid;
    width: 1.35rem;
    height: 1.35rem;
    margin-left: auto;
    place-items: center;
    border-radius: 6px;
    font-size: 0.62rem;
    transform: rotate(-90deg);
    transition: transform 0.18s ease, background-color 0.15s ease;
}

.nav-group.open > .nav-group-toggle .toggle-icon {
    transform: rotate(0deg);
}

.nav-group-toggle:hover {
    color: var(--text-primary);
    background: var(--bg-tertiary);
}

.nav-group-toggle:hover .toggle-icon {
    background: var(--bg-secondary);
}

.nav-submenu {
    max-height: 0;
    margin: 0 0.72rem 0 1.05rem;
    padding: 0 0 0 0.62rem;
    overflow: hidden;
    visibility: hidden;
    opacity: 0;
    background: transparent;
    border-left: 1px solid transparent;
    transition: max-height 0.2s ease, opacity 0.14s ease,
                padding 0.2s ease, border-color 0.2s ease;
}

.nav-group.open > .nav-submenu {
    max-height: 2200px;
    padding-top: 0.08rem;
    padding-bottom: 0.08rem;
    visibility: visible;
    opacity: 1;
    border-left-color: var(--border-color);
}

.nav-submenu .nav-link {
    margin: 0.08rem 0;
    padding: 0.56rem 0.68rem;
    border: 0;
    border-radius: 8px;
    font-size: 0.86rem;
    line-height: 1.32;
}

.nav-submenu .nav-link:hover {
    padding-left: 0.68rem;
    transform: none;
}

/* РЎСЃС‹Р»РєРё РЅР° РґСЂСѓРіРёРµ РїСЂРµРґРјРµС‚С‹ - Р°РґР°РїС‚РёРІРЅС‹Рµ Рє С‚РµРјРµ */
.nav-section.other-subjects a {
    color: var(--text-primary);
    text-decoration: none;
    transition: var(--transition);
}

.nav-section.other-subjects a:hover {
    opacity: 0.7;
}

.nav-section.other-subjects a.current-subject {
    font-weight: 600;
    opacity: 1;
    color: var(--text-primary);
}

body.dark-theme .nav-section.other-subjects a:hover {
    opacity: 0.8;
}

/* РЎС‚РёР»Рё РґР»СЏ РєРЅРѕРїРєРё Р·Р°С‡С‘С‚Р° РІ С‚РµРјРЅРѕР№ С‚РµРјРµ */
body.dark-theme .nav-link[href="physics 07.02.html"] {
    background: linear-gradient(135deg, #4c1d95 0%, #5b21b6 100%) !important;
    color: white !important;
}

body.dark-theme .nav-link[href="physics 07.02.html"]:hover {
    background: linear-gradient(135deg, #5b21b6 0%, #6d28d9 100%) !important;
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgba(139, 92, 246, 0.3);
}

/* РљРЅРѕРїРєР° СЃРІРѕСЂР°С‡РёРІР°РЅРёСЏ СЃР°Р№РґР±Р°СЂР° (РІРЅСѓС‚СЂРё С…РµРґРµСЂР°, РґРµСЃРєС‚РѕРї) */
.sidebar-collapse-btn {
    display: none;
    background: rgba(255, 255, 255, 0.2);
    border: none;
    color: white;
    width: 32px;
    height: 32px;
    border-radius: 50%;
    cursor: pointer;
    font-size: 1rem;
    transition: var(--transition);
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    line-height: 1;
    padding: 0;
}

.sidebar-collapse-btn:hover {
    background: rgba(255, 255, 255, 0.3);
}

/* РљРЅРѕРїРєР° РѕС‚РєСЂС‹С‚РёСЏ СЃРІС‘СЂРЅСѓС‚РѕРіРѕ СЃР°Р№РґР±Р°СЂР° (РїРѕСЏРІР»СЏРµС‚СЃСЏ РєРѕРіРґР° СЃР°Р№РґР±Р°СЂ СЃРєСЂС‹С‚) */
.sidebar-expand-btn {
    display: none;
    position: fixed;
    top: 0.85rem;
    left: 0.85rem;
    width: 34px;
    height: 34px;
    background: var(--bg-secondary);
    color: var(--text-secondary);
    border: 1px solid var(--border-color);
    border-radius: 9px;
    font-size: 1rem;
    cursor: pointer;
    z-index: 1001;
    box-shadow: var(--shadow-sm);
    transition: background-color 0.2s ease,
                transform 0.2s ease,
                opacity 0.3s ease;
    line-height: 1;
    padding: 0;
    align-items: center;
    justify-content: center;
    opacity: 0;
    pointer-events: none;
}

.sidebar-expand-btn:hover {
    color: var(--text-primary);
    background: var(--bg-tertiary);
    border-color: color-mix(in srgb, var(--accent-color) 30%, var(--border-color));
    transform: translateX(1px);
}

/* РЎРѕСЃС‚РѕСЏРЅРёРµ СЃРІС‘СЂРЅСѓС‚РѕРіРѕ СЃР°Р№РґР±Р°СЂР° */
.sidebar.collapsed {
    transform: translateX(-100%);
}

body.sidebar-collapsed .sidebar-expand-btn {
    display: flex;
    opacity: 1;
    pointer-events: auto;
}

body.sidebar-collapsed .main-content {
    margin-left: 0;
    max-width: 100%;
    /* Сайдбар свёрнут — центрируем широкую колонку по всему экрану */
    padding: 2rem max(2rem, calc((100vw - 1400px) / 2)) 2rem;
}

/* РљРЅРѕРїРєР° РјРµРЅСЋ (РјРѕР±РёР»СЊРЅС‹Рµ) */
.menu-toggle {
    display: none;
    position: fixed;
    top: 1rem;
    left: 1rem;
    width: 48px;
    height: 48px;
    background: var(--accent-color);
    color: white;
    border: none;
    border-radius: 12px;
    font-size: 1.5rem;
    cursor: pointer;
    z-index: 999;
    box-shadow: var(--shadow-lg);
    transition: var(--transition);
}

.menu-toggle:hover {
    background: var(--accent-hover);
    transform: scale(1.05);
}

/* РљРЅРѕРїРєР° РїРµСЂРµРєР»СЋС‡РµРЅРёСЏ С‚РµРјС‹ */
.theme-toggle {
    width: 40px;
    height: 40px;
    background: rgba(255, 255, 255, 0.2);
    color: white;
    border: none;
    border-radius: 50%;
    font-size: 1.3rem;
    cursor: pointer;
    box-shadow: var(--shadow-sm);
    transition: var(--transition);
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    position: relative;
    overflow: visible;
}

.theme-toggle::before {
    content: '';
    position: absolute;
    width: 100%;
    height: 100%;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.4);
    transform: scale(0);
    opacity: 0;
    transition: transform 0.4s ease, opacity 0.4s ease;
}

.theme-toggle:hover::before {
    transform: scale(1.3);
    opacity: 1;
}

.theme-toggle:hover {
    background: rgba(255, 255, 255, 0.3);
    transform: scale(1.1);
}

.theme-toggle:active {
    transform: scale(0.95);
}

/* ============================================
   РћРЎРќРћР’РќРћР™ РљРћРќРўР•РќРў
   ============================================ */

.main-content {
    margin-left: var(--sidebar-width);
    /* Широкая колонка контента: блоки занимают большую часть доступной ширины
       на десктопе. Кап ~1400px не даёт строкам растягиваться до абсурда на 4K,
       но на типичных ноутбуках/мониторах контент почти во всю ширину. */
    padding: 2rem max(2rem, calc((100vw - var(--sidebar-width) - 1400px) / 2)) 2rem;
    max-width: calc(100vw - var(--sidebar-width)); /* по ширине экрана минус сайдбар */
    transition: margin-left 0.3s ease, max-width 0.3s ease;
}

/* Заголовок страницы */
.page-header {
    text-align: center;
    padding: 3rem 2rem;
    background: var(--header-bg);
    color: var(--header-text);
    border-radius: var(--border-radius-lg);
    margin-bottom: 2.5rem;
    box-shadow: var(--shadow-lg);
    position: relative;
    overflow: hidden;
    transition: background 0.3s ease,
                box-shadow 0.3s ease;
}

body.dark-theme .page-header {
    border: none;
    box-shadow: var(--shadow-xl);
}

.page-header h1 {
    font-size: 2.5rem;
    font-weight: 700;
    margin-bottom: 0.75rem;
    position: relative;
    letter-spacing: -0.02em;
}

.subtitle {
    font-size: 1.05rem;
    opacity: 0.7;
    position: relative;
}

/* Р Р°Р·РґРµР»С‹ РєРѕРЅС‚РµРЅС‚Р° */
.content-section {
    margin-bottom: 2rem;
    transition: background-color 0.3s ease,
                color 0.3s ease;
}

/* Персональный масштаб относится к материалу и его локальной навигации:
   сайдбар, плавающие кнопки и модальные окна сохраняют обычный размер. CSS zoom
   здесь выбран намеренно — он пересчитывает раскладку, поэтому текст не обрезается. */
body[data-note-subject] .main-content > .page-header,
body[data-note-subject] .main-content > .content-section,
body[data-note-subject] .main-content > .exp-reader-toolbar,
body[data-note-subject] .main-content > .note-reader-controls,
body[data-note-subject] .main-content > .exp-reader-footer {
    zoom: var(--note-scale, 1);
}

.notes-empty-state {
    min-height: min(48vh, 430px);
    padding: clamp(2.5rem, 7vw, 5.5rem) 1.5rem;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
    color: var(--text-secondary);
    background: var(--bg-secondary);
    border: 1px solid var(--border-color);
    border-radius: var(--border-radius-lg);
    box-shadow: var(--shadow-sm);
}

.notes-empty-icon {
