    font-size: 1.18em;
}

.katex-display {
    margin: 1rem 0;
    overflow-x: auto;
    overflow-y: hidden;
}

/* ============================================
   Р¤РЈРўР•Р 
   ============================================ */

.page-footer {
    text-align: center;
    padding: 2rem;
    margin-top: 3rem;
    border-top: 2px solid var(--border-color);
    color: var(--text-secondary);
}

.page-footer p {
    margin: 0.5rem 0;
}

/* ============================================
   РљРќРћРџРљРђ "РќРђР’Р•Р РҐ"
   ============================================ */

.scroll-to-top {
    position: fixed;
    bottom: 2rem;
    right: 2rem;
    width: 50px;
    height: 50px;
    background: var(--accent-color);
    color: white;
    border: none;
    border-radius: 50%;
    cursor: pointer;
    opacity: 0;
    visibility: hidden;
    transition: var(--transition);
    box-shadow: var(--shadow-lg);
    z-index: 999;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 0;
}

.scroll-to-top svg {
    width: 22px;
    height: 22px;
    display: block;
}

.scroll-to-top.visible {
    opacity: 1;
    visibility: visible;
}

.scroll-to-top:hover {
    background: var(--accent-hover);
    transform: translateY(-5px);
}

/* ============================================
   РђР”РђРџРўРР’РќРћРЎРўР¬
   ============================================ */

/* РџРѕРєР°Р· РєРЅРѕРїРєРё СЃРІРѕСЂР°С‡РёРІР°РЅРёСЏ РЅР° С€РёСЂРѕРєРёС… СЌРєСЂР°РЅР°С… */
@media (min-width: 769px) {
    .sidebar-collapse-btn {
        display: flex;
    }
}

@media (max-width: 1024px) {
    :root {
        --sidebar-width: 280px;
    }
    
    .page-header h1 {
        font-size: 2rem;
    }
    
    .topic-title {
        font-size: 1.5rem;
    }
}

/* ============================================
   РњРћР‘РР›Р¬РќР«Р™ Р”РР—РђР™Рќ: CLEAN READER
   ============================================ */

@media (max-width: 768px) {
    :root {
        --m-pad: 1.59rem;
    }

    body {
        font-size: 16px;
        line-height: 1.65;
        max-width: 100vw;
    }

    /* --- SIDEBAR: BOTTOM SHEET --- */
    .sidebar {
        top: auto;
        bottom: 0;
        left: 0;
        right: 0;
        width: 100%;
        max-height: 80vh;
        max-height: 80dvh;
        transform: translateY(100%);
        border-radius: 16px 16px 0 0;
        border-right: none;
        border-top: 1px solid var(--border-color);
        -webkit-overflow-scrolling: touch;
        overscroll-behavior: contain;
        box-shadow: 0 -4px 24px rgba(0, 0, 0, 0.15);
    }

    .sidebar.open {
        transform: translateY(0);
    }

    .sidebar-collapse-btn,
    .sidebar-expand-btn {
        display: none !important;
    }

    .sidebar::before {
        content: '';
        display: block;
        width: 40px;
        height: 4px;
        background: var(--border-color);
        border-radius: 2px;
        margin: 8px auto 4px;
        flex-shrink: 0;
    }

    .close-sidebar {
        display: flex;
        min-width: 44px;
        min-height: 44px;
        width: 34px;
        height: 34px;
        font-size: 1.1rem;
    }

    .menu-toggle {
        display: flex;
        left: auto;
        right: 0.75rem;
        top: auto;
        bottom: 1rem;
    }

    .sidebar-header {
        flex-wrap: nowrap;
        gap: 0.5rem;
        padding: 0.5rem 1rem 0.625rem;
    }

    .sidebar-header h2 {
        font-size: 1.1rem;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }

    .theme-toggle {
