    }

    .search-box {
        padding: 0.375rem var(--m-pad);
    }

    .search-box input {
        padding: 0.55rem 0.875rem;
        font-size: 0.9rem;
        border-radius: 8px;
    }

    .search-nav-bar {
        padding: 0.4rem 0.75rem;
        gap: 0.5rem;
    }

    .search-nav-sections {
