    }

    .nav-submenu .nav-link:hover {
        padding-left: 1.75rem;
        transform: none;
    }

    .nav-link:hover {
        transform: none;
    }

    /* --- MAIN CONTENT: EDGE-TO-EDGE --- */
    .main-content {
        margin-left: 0;
        padding: 0;
        max-width: 100vw;
        width: 100%;
        overflow-x: clip;
    }

    /* --- PAGE HEADER: COMPACT STRIP --- */
    .page-header {
        border-radius: 0;
        padding: 1.25rem var(--m-pad);
        margin-bottom: 0;
        box-shadow: none;
    }

    .page-header::before {
