@media (max-width: 768px) {
    .sidebar .sidebar-header {
        min-height: 58px;
        padding: 0.5rem 0.72rem 0.58rem;
    }

    .sidebar .sidebar-header h2 {
        display: block;
        font-size: 0.98rem;
        -webkit-line-clamp: initial;
        line-clamp: initial;
    }

    .sidebar-header-buttons > .account-btn,
    .sidebar-header-buttons > .settings-button-sidebar,
    .sidebar-header-buttons > .close-sidebar {
        width: 40px;
        min-width: 40px;
        height: 40px;
        min-height: 40px;
    }
}


/* ============================================
   РќРћР’РћР“РћР”РќРР™ Р’РђР™Р‘
   ============================================ */

/* РљРЅРѕРїРєР° РЅРѕРІРѕРіРѕРґРЅРµРіРѕ СЂРµР¶РёРјР° */
.ny-toggle {
    display: none !important;
    background: linear-gradient(135deg, #2d5016 0%, #4a7c2e 100%);
    border: none;
    width: 40px;
    height: 40px;
    border-radius: 12px;
    font-size: 1.3rem;
    cursor: pointer;
    transition: var(--transition);
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: var(--shadow-sm);
    margin-left: 0.5rem;
    position: relative;
}

/* Р’РёР·СѓР°Р»СЊРЅРѕРµ СЂР°Р·РґРµР»РµРЅРёРµ РєРЅРѕРїРєРё */
.ny-toggle::before {
    content: '';
    position: absolute;
    left: -0.5rem;
    top: 50%;
    transform: translateY(-50%);
    width: 1px;
    height: 60%;
    background: rgba(255, 255, 255, 0.3);
}

.ny-toggle:hover {
    transform: scale(1.15) rotate(5deg);
    box-shadow: 0 4px 16px rgba(74, 124, 46, 0.4);
}

.ny-toggle:active {
    transform: scale(0.95);
}

/* РљРѕРЅС‚РµР№РЅРµСЂ РґР»СЏ СЃРЅРµРіР° */
.snow-container {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    z-index: 9999;
    overflow: hidden;
}

/* РЎРЅРµР¶РёРЅРєР° */
.snowflake {
    position: fixed;
    left: 0;
    top: 0;
    color: #a0c4e8;
    pointer-events: none;
    user-select: none;
    text-shadow: 0 0 5px rgba(160, 196, 232, 0.6);
    will-change: transform, opacity;
}

/* РЎРЅРµР¶РёРЅРєРё РґР»СЏ С‚С‘РјРЅРѕР№ С‚РµРјС‹ */
body.dark-theme .snowflake {
    color: #fff;
    text-shadow: 0 0 5px rgba(255, 255, 255, 0.8);
}

/* РћРїС‚РёРјРёР·Р°С†РёСЏ РґР»СЏ РјРѕР±РёР»СЊРЅС‹С… СѓСЃС‚СЂРѕР№СЃС‚РІ */
@media (max-width: 768px) {
    .snowflake {
        /* РЈРїСЂРѕС‰Р°РµРј Р°РЅРёРјР°С†РёСЋ РЅР° РјРѕР±РёР»СЊРЅС‹С… РґР»СЏ Р»СѓС‡С€РµР№ РїСЂРѕРёР·РІРѕРґРёС‚РµР»СЊРЅРѕСЃС‚Рё */
        will-change: transform;
        transform: translateZ(0); /* Р’РєР»СЋС‡Р°РµРј Р°РїРїР°СЂР°С‚РЅРѕРµ СѓСЃРєРѕСЂРµРЅРёРµ */
        backface-visibility: hidden;
        -webkit-backface-visibility: hidden;
    }
}

/* РљРѕРЅС‚РµР№РЅРµСЂ РґР»СЏ РїР°СЃС…Р°Р»РѕРє */
.easter-eggs-container {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    z-index: 10000;
    overflow: hidden;
}

/* РџР°СЃС…Р°Р»РєР° (РІСЃРїР»С‹РІР°СЋС‰РёР№ emoji) */
.easter-egg {
    position: fixed;
    font-size: 2rem;
    pointer-events: none;
    user-select: none;
    animation: float-up 2s ease-out forwards;
    z-index: 10001;
}

@keyframes float-up {
    0% {
        transform: translateY(0) scale(0.5) rotate(0deg);
        opacity: 1;
    }
    50% {
        transform: translateY(-100px) scale(1.2) rotate(180deg);
        opacity: 0.8;
    }
    100% {
        transform: translateY(-200px) scale(0.8) rotate(360deg);
        opacity: 0;
    }
}

/* РЈРІРµРґРѕРјР»РµРЅРёРµ Рѕ РІРєР»СЋС‡РµРЅРёРё СЂРµР¶РёРјР° */
.ny-notification {
    position: fixed;
    top: 100px;
    right: 20px;
    background: linear-gradient(135deg, #2d5016 0%, #4a7c2e 100%);
    color: white;
    padding: 1rem 1.5rem;
    border-radius: 12px;
    font-size: 1.1rem;
    font-weight: 600;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
    transform: translateX(400px);
    transition: transform 0.3s cubic-bezier(0.68, -0.55, 0.265, 1.55);
    z-index: 10002;
    pointer-events: none;
}

.ny-notification.show {
    transform: translateX(0);
}

/* РќРѕРІРѕРіРѕРґРЅРёРµ СѓРєСЂР°С€РµРЅРёСЏ РґР»СЏ РєР°СЂС‚РѕС‡РµРє СЃС‚Р°С‚РёСЃС‚РёРєРё */
body.new-year-mode .stat-card.ny-decorated {
    position: relative;
    overflow: visible;
}

body.new-year-mode .stat-card.ny-decorated::before {
    content: '✨';
    position: absolute;
    top: -10px;
    right: -10px;
    font-size: 1.5rem;
    animation: sparkle 2s ease-in-out infinite;
}

body.new-year-mode .stat-card.ny-decorated:nth-child(2)::before {
    content: '🎁';
}

body.new-year-mode .stat-card.ny-decorated:nth-child(3)::before {
    content: '⭐';
}

body.new-year-mode .stat-card.ny-decorated:nth-child(4)::before {
    content: '🎄';
}

@keyframes sparkle {
    0%, 100% {
        transform: scale(1) rotate(-20deg);
        opacity: 0.8;
    }
    50% {
        transform: scale(1.3) rotate(20deg);
        opacity: 1;
    }
}

/* РќРѕРІРѕРіРѕРґРЅРёР№ СЌС„С„РµРєС‚ РґР»СЏ header */
body.new-year-mode .page-header {
    position: relative;
}

body.new-year-mode .page-header::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: 
        radial-gradient(circle at 20% 50%, rgba(255, 215, 0, 0.1) 0%, transparent 50%),
        radial-gradient(circle at 80% 50%, rgba(74, 124, 46, 0.1) 0%, transparent 50%);
    pointer-events: none;
    animation: shimmer 3s ease-in-out infinite;
}

@keyframes shimmer {
    0%, 100% { opacity: 0.5; }
    50% { opacity: 1; }
}

/* РђРЅРёРјР°С†РёСЏ РґР»СЏ РєРЅРѕРїРєРё РЅРѕРІРѕРіРѕРґРЅРµРіРѕ СЂРµР¶РёРјР° РІ Р°РєС‚РёРІРЅРѕРј СЃРѕСЃС‚РѕСЏРЅРёРё */
body.new-year-mode .ny-toggle {
    animation: glow-pulse 2s ease-in-out infinite;
}

@keyframes glow-pulse {
    0%, 100% {
        box-shadow: 0 0 20px rgba(255, 215, 0, 0.6);
    }
    50% {
        box-shadow: 0 0 30px rgba(255, 215, 0, 0.9);
    }
}

/* РњРѕРґР°Р»СЊРЅРѕРµ РѕРєРЅРѕ РЅР°СЃС‚СЂРѕРµРє */
.ny-settings-modal {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.7);
    backdrop-filter: blur(5px);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 10003;
    opacity: 1;
    transition: opacity 0.3s ease;
}

.ny-settings-modal.hidden {
    visibility: hidden;
    opacity: 0;
    pointer-events: none;
}

.ny-settings-content {
    background: var(--bg-primary);
    border-radius: 20px;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.4);
    max-width: 500px;
    width: 90%;
    max-height: 90vh;
    overflow-y: auto;
    animation: modalSlideIn 0.42s var(--ease-spring);
}

@keyframes modalSlideIn {
    from {
        transform: scale(0.96) translateY(8px);
        opacity: 0;
    }
    to {
        transform: scale(1) translateY(0);
        opacity: 1;
    }
}

.ny-settings-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1.5rem;
    border-bottom: 2px solid var(--border-color);
    background: linear-gradient(135deg, #2d5016 0%, #4a7c2e 100%);
    border-radius: 20px 20px 0 0;
}

.ny-settings-header h3 {
    color: white;
    font-size: 1.3rem;
    margin: 0;
    font-weight: 600;
}

.ny-settings-close {
    background: rgba(255, 255, 255, 0.2);
    border: none;
    color: white;
    width: 32px;
    height: 32px;
    border-radius: 50%;
    cursor: pointer;
    font-size: 1.2rem;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: var(--transition);
}

.ny-settings-close:hover {
    background: rgba(255, 255, 255, 0.3);
    transform: rotate(90deg);
}

.ny-settings-body {
    padding: 1.5rem;
}

.ny-setting-item {
    margin-bottom: 1.5rem;
}

.ny-setting-item:last-child {
    margin-bottom: 0;
}

.ny-setting-item label {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.ny-setting-item label > span:first-child {
    color: var(--text-primary);
    font-weight: 600;
    font-size: 0.95rem;
}

.ny-setting-item input[type="range"] {
    width: 100%;
    height: 8px;
    border-radius: 5px;
    background: var(--bg-tertiary);
    outline: none;
    -webkit-appearance: none;
    appearance: none;
}

.ny-setting-item input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    width: 20px;
    height: 20px;
    border-radius: 50%;
    background: linear-gradient(135deg, #2d5016 0%, #4a7c2e 100%);
    cursor: pointer;
    box-shadow: 0 2px 8px rgba(74, 124, 46, 0.4);
    transition: var(--transition);
}

.ny-setting-item input[type="range"]::-webkit-slider-thumb:hover {
    transform: scale(1.2);
    box-shadow: 0 4px 12px rgba(74, 124, 46, 0.6);
}

.ny-setting-item input[type="range"]::-moz-range-thumb {
    width: 20px;
    height: 20px;
    border-radius: 50%;
    background: linear-gradient(135deg, #2d5016 0%, #4a7c2e 100%);
    cursor: pointer;
    border: none;
    box-shadow: 0 2px 8px rgba(74, 124, 46, 0.4);
    transition: var(--transition);
}

.ny-setting-item input[type="range"]::-moz-range-thumb:hover {
    transform: scale(1.2);
    box-shadow: 0 4px 12px rgba(74, 124, 46, 0.6);
}

.ny-setting-value {
    color: var(--text-primary);
    font-weight: 600;
    font-size: 0.9rem;
    text-align: right;
}

.ny-settings-footer {
    display: flex;
    gap: 1rem;
    padding: 1.5rem;
    border-top: 2px solid var(--border-color);
    background: var(--bg-secondary);
    border-radius: 0 0 20px 20px;
}

.ny-settings-reset,
.ny-settings-apply {
    flex: 1;
    padding: 0.8rem 1.5rem;
    border: none;
    border-radius: 12px;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: var(--transition);
}

.ny-settings-reset {
    background: var(--bg-tertiary);
    color: var(--text-primary);
}

.ny-settings-reset:hover {
    background: var(--border-color);
