/* Shared settings layout, including deferred note pages. */
.settings-modal .settings-modal-content {
    width: min(600px, calc(100% - 32px));
    max-width: 600px;
    max-height: min(90dvh, 820px);
    background: color-mix(in srgb, var(--bg-primary) 96%, var(--accent-color) 4%);
    border-color: color-mix(in srgb, var(--border-color) 82%, var(--accent-color) 18%);
    border-radius: 22px;
    box-shadow: 0 26px 80px -22px rgba(8, 15, 35, 0.58);
}

.settings-modal .settings-modal-header {
    flex-shrink: 0;
    padding: 0.9rem 1.25rem;
    background: var(--bg-primary);
    border-radius: 22px 22px 0 0;
}

.settings-modal .settings-modal-body {
    display: grid;
    align-content: start;
    gap: 1.25rem;
    padding: 1.15rem 1.25rem;
    overscroll-behavior: contain;
    scrollbar-gutter: stable;
}

.settings-modal .settings-section,
.settings-modal .settings-section:last-of-type {
    box-sizing: border-box;
    width: 100%;
    min-width: 0;
    margin: 0;
    padding: 0;
    background: transparent;
    border: 0;
    box-shadow: none;
}

.settings-modal .settings-section + .settings-section {
    padding-top: 0;
}

.settings-modal .settings-section h3 {
    margin: 0;
    font-size: 0.98rem;
    line-height: 1.2;
}

.settings-modal .settings-section h3 .settings-section-icon {
    box-sizing: content-box;
    width: 17px;
    height: 17px;
    padding: 0.2rem;
    color: var(--accent-color);
    background: transparent;
    border-radius: 10px;
}

.settings-modal .settings-option {
    width: 100%;
    margin-top: 0.8rem;
}

.settings-modal .animation-level-selector {
    display: grid;
    grid-template-columns: 1fr;
    gap: 0.55rem;
}

.settings-modal .animation-level-option {
    box-sizing: border-box;
    display: grid;
    grid-template-columns: 30px minmax(0, 1fr);
    align-items: center;
    column-gap: 0.65rem;
    min-width: 0;
    min-height: 62px;
    padding: 0.78rem;
    border-width: 1px;
    border-radius: 10px;
    line-height: 1;
}

.settings-modal .animation-level-option .level-icon {
    width: 26px;
    height: 26px;
}

.settings-modal .animation-level-option .level-icon-svg {
    width: 21px;
    height: 21px;
}

.settings-modal .animation-level-option .level-copy {
    display: grid;
    align-content: center;
    gap: 0.22rem;
    min-width: 0;
    min-height: 42px;
}

.settings-modal .animation-level-option .level-title {
    margin: 0;
    font-size: 0.83rem;
    line-height: 1.2;
}

.settings-modal .animation-level-option .level-desc {
    margin: 0;
    font-size: 0.7rem;
    line-height: 1.32;
}

.settings-modal .toggle-switch {
    box-sizing: border-box;
    width: 100%;
    padding: 0.8rem 0.9rem;
    background: var(--bg-secondary);
    border: 1px solid var(--border-color);
    border-radius: 10px;
}

.settings-modal .settings-actions {
    flex-shrink: 0;
    justify-content: space-between;
    gap: 12px;
    margin: 0;
    padding: 0.75rem 1.25rem max(0.75rem, env(safe-area-inset-bottom));
    border-top: 1px solid var(--border-color);
}

.settings-modal .settings-reset-btn {
    width: auto;
    padding: 0.55rem 0.75rem;
    background: transparent;
    border-color: transparent;
    font-size: 0.76rem;
}

.settings-modal .settings-section-heading {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.5rem;
}

.settings-modal .note-scale-control {
    display: grid;
    grid-template-columns: 90px minmax(0, 1fr);
    align-items: center;
    gap: 1rem;
    margin-top: 0.9rem;
}

.settings-modal .note-scale-reset {
    flex: 0 0 auto;
    min-height: 44px;
    padding: 0.42rem 0.68rem;
    color: var(--text-secondary);
    background: color-mix(in srgb, var(--bg-primary) 84%, transparent);
    border: 1px solid color-mix(in srgb, var(--border-color) 84%, transparent);
    border-radius: 9px;
    font: inherit;
    font-size: 0.72rem;
    font-weight: 680;
    line-height: 1.15;
    cursor: pointer;
    transition: color 0.15s ease, background-color 0.15s ease, border-color 0.15s ease;
}

.settings-modal .note-scale-number {
    display: grid;
    gap: 0.38rem;
    min-width: 0;
    color: var(--text-secondary);
    font-size: 0.7rem;
    font-weight: 650;
    letter-spacing: 0.01em;
}

.settings-modal .note-scale-input-wrap {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
    min-height: 44px;
    padding: 0 0.78rem;
    color: var(--text-secondary);
    background: var(--bg-primary);
    border: 1px solid var(--border-color);
    border-radius: 11px;
    transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.settings-modal .note-scale-input-wrap:focus-within {
    border-color: var(--accent-color);
    box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent-color) 13%, transparent);
}

.settings-modal .note-scale-input-wrap input {
    width: 100%;
    min-width: 0;
    padding: 0;
    color: var(--text-primary);
    background: transparent;
    border: 0;
    outline: 0;
    font: inherit;
    font-size: 1rem;
    font-weight: 750;
    font-variant-numeric: tabular-nums;
    -moz-appearance: textfield;
}

.settings-modal .note-scale-input-wrap input::-webkit-inner-spin-button,
.settings-modal .note-scale-input-wrap input::-webkit-outer-spin-button {
    margin: 0;
    -webkit-appearance: none;
}

.settings-modal .note-scale-slider-wrap {
    display: grid;
    gap: 0.38rem;
    min-width: 0;
    padding-bottom: 0.08rem;
}

.settings-modal .note-scale-slider {
    width: 100%;
    min-height: 30px;
    margin: 0;
    accent-color: var(--accent-color);
    cursor: pointer;
}

.settings-modal .note-scale-limits {
    display: flex;
    justify-content: space-between;
    color: var(--text-secondary);
    font-size: 0.65rem;
    font-variant-numeric: tabular-nums;
}

.settings-modal .note-scale-reset:hover {
    color: var(--accent-color);
    border-color: color-mix(in srgb, var(--accent-color) 52%, var(--border-color));
    background: color-mix(in srgb, var(--accent-color) 8%, var(--bg-primary));
}

.settings-modal :is(.settings-section-icon, .level-icon-svg, .settings-close-btn svg, .settings-reset-btn svg) {
    display: block;
    flex: 0 0 auto;
    max-width: none;
    aspect-ratio: 1;
    overflow: visible;
}

@media (max-width: 768px) {
    .settings-modal .settings-modal-content {
        width: 100%;
        max-height: 90dvh;
        border-radius: 18px 18px 0 0;
    }

    .settings-modal .settings-modal-header {
        padding: 0.85rem 1.1rem 0.9rem;
