}

.settings-modal .design-mode-selector { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.settings-modal .design-mode-option { min-height: 68px; padding: 12px 30px 12px 12px; }
.settings-modal .settings-option .exp-subpanel { margin-top: 16px; background: transparent; }
.settings-modal .settings-option .exp-mode-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.settings-modal .exp-mode-card { min-height: 60px; padding: 10px 12px; gap: 8px; }
