/* ============================================
   TELEGRAM РљРћРњРњРЈРќРРљРђР¦РРЇ
   ============================================ */

/* РљРѕРЅС‚РµР№РЅРµСЂ РґР»СЏ СѓРІРµРґРѕРјР»РµРЅРёР№ */
.telegram-notifications-container {
    position: fixed;
    top: 20px;
    right: 20px;
    z-index: 10005;
    display: flex;
    flex-direction: column;
    gap: 10px;
    max-width: 380px;
    pointer-events: none;
}

/* РЈРІРµРґРѕРјР»РµРЅРёРµ */
.telegram-notification {
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    color: white;
    border-radius: 16px;
    padding: 1rem;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
    transform: translateX(400px);
    opacity: 0;
    transition: var(--transition-bounce);
    pointer-events: auto;
    position: relative;
    max-width: 380px;
    word-wrap: break-word;
}

.telegram-notification.show {
    transform: translateX(0);
    opacity: 1;
}

.telegram-notification-header {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 0.5rem;
    font-weight: 600;
}

.telegram-notification-icon {
    font-size: 1.2rem;
}

.telegram-notification-title {
    font-size: 0.95rem;
}

.telegram-notification-body {
    font-size: 0.9rem;
    line-height: 1.5;
    opacity: 0.95;
    white-space: pre-wrap;
    word-break: break-word;
}

.telegram-notification-close {
    position: absolute;
    top: 8px;
    right: 8px;
    background: rgba(255, 255, 255, 0.2);
    border: none;
    color: white;
    width: 24px;
    height: 24px;
    border-radius: 50%;
    cursor: pointer;
    font-size: 0.9rem;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: background 0.2s;
}

.telegram-notification-close:hover {
    background: rgba(255, 255, 255, 0.3);
}

/* РџР»Р°РІР°СЋС‰Р°СЏ РєРЅРѕРїРєР° С‡Р°С‚Р° */
.telegram-chat-button {
    position: fixed;
    bottom: 2rem;
    left: 2rem;
    width: 60px;
    height: 60px;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    color: white;
    border: none;
    border-radius: 50%;
    font-size: 1.8rem;
    cursor: pointer;
    box-shadow: 0 8px 24px rgba(102, 126, 234, 0.4);
    transition: var(--transition);
    z-index: 999;
    display: flex;
    align-items: center;
    justify-content: center;
}

.telegram-chat-button:hover {
    transform: scale(1.1);
    box-shadow: 0 12px 32px rgba(102, 126, 234, 0.6);
}

.telegram-chat-button:active {
    transform: scale(0.95);
}

/* Р”РёР°Р»РѕРіРѕРІРѕРµ РѕРєРЅРѕ */
.telegram-dialog {
    position: fixed;
    bottom: 100px;
    left: 20px;
    width: 400px;
    max-width: calc(100vw - 40px);
    height: 500px;
    max-height: calc(100vh - 140px);
    max-height: calc(100dvh - 140px);
    background: var(--bg-primary);
    border-radius: 20px;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.4);
    z-index: 10000;
    display: flex;
    flex-direction: column;
    opacity: 1;
    transform: scale(1) translateY(0);
    transition: var(--transition-bounce);
}

.telegram-dialog.hidden {
    opacity: 0;
    transform: scale(0.8) translateY(20px);
    pointer-events: none;
}

.telegram-dialog-header {
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    color: white;
    padding: 1rem 1.5rem;
    border-radius: 20px 20px 0 0;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.telegram-dialog-header h3 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 600;
}

.telegram-close-btn {
    background: rgba(255, 255, 255, 0.2);
    border: none;
    color: white;
    width: 32px;
    height: 32px;
    border-radius: 50%;
    cursor: pointer;
    font-size: 1.2rem;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: background 0.2s;
}

.telegram-close-btn:hover {
    background: rgba(255, 255, 255, 0.3);
    transform: rotate(90deg);
}

.telegram-dialog-body {
    display: flex;
    flex-direction: column;
    flex: 1;
    overflow: hidden;
}

.telegram-messages {
    flex: 1;
    overflow-y: auto;
    padding: 1rem;
    background: var(--bg-secondary);
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.telegram-messages::-webkit-scrollbar {
    width: 6px;
}

.telegram-messages::-webkit-scrollbar-track {
    background: var(--bg-tertiary);
}

.telegram-messages::-webkit-scrollbar-thumb {
    background: var(--accent-color);
    border-radius: 3px;
}

.telegram-welcome-message {
    background: linear-gradient(135deg, rgba(102, 126, 234, 0.1), rgba(118, 75, 162, 0.1));
    color: var(--text-primary);
    padding: 1rem;
    border-radius: 12px;
    border-left: 4px solid #667eea;
    font-size: 0.95rem;
    line-height: 1.6;
}

.telegram-message {
    max-width: 80%;
    padding: 0.75rem 1rem;
    border-radius: 12px;
    word-wrap: break-word;
    animation: messageSlideIn 0.3s ease;
}

@keyframes messageSlideIn {
    from {
        opacity: 0;
        transform: translateY(10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.telegram-message-user {
    align-self: flex-end;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    color: white;
    border-radius: 12px 12px 4px 12px;
}

.telegram-message-admin {
    align-self: flex-start;
    background: var(--bg-primary);
    color: var(--text-primary);
    border: 2px solid var(--border-color);
    border-radius: 12px 12px 12px 4px;
}

.telegram-message-system {
    align-self: center;
    background: rgba(102, 126, 234, 0.1);
    color: var(--text-secondary);
    font-size: 0.85rem;
    padding: 0.5rem 0.75rem;
    border-radius: 8px;
    max-width: 90%;
    text-align: center;
}

.telegram-message-text {
    font-size: 0.95rem;
    line-height: 1.5;
    margin-bottom: 0.25rem;
}

.telegram-message-time {
    font-size: 0.75rem;
    opacity: 0.7;
    text-align: right;
}

.telegram-input-container {
    padding: 1rem;
    background: var(--bg-primary);
    border-top: 2px solid var(--border-color);
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

#telegramMessageInput {
    width: 100%;
    padding: 0.75rem;
    border: 2px solid var(--border-color);
    border-radius: 12px;
    background: var(--bg-secondary);
    color: var(--text-primary);
    font-size: 0.95rem;
    font-family: inherit;
    resize: none;
    transition: border-color 0.3s ease;
}

#telegramMessageInput:focus {
    outline: none;
    border-color: var(--accent-color);
    box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.1);
}

.telegram-send-btn {
    padding: 0.75rem 1.5rem;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    color: white;
    border: none;
    border-radius: 12px;
    font-size: 0.95rem;
    font-weight: 600;
    cursor: pointer;
    transition: var(--transition);
    box-shadow: 0 4px 12px rgba(102, 126, 234, 0.3);
}

.telegram-send-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(102, 126, 234, 0.4);
}

.telegram-send-btn:active {
    transform: translateY(0);
}

/* РђРґР°РїС‚Р°С†РёСЏ РґР»СЏ РјРѕР±РёР»СЊРЅС‹С… */
@media (max-width: 768px) {
    .telegram-notifications-container {
        top: 10px;
        right: 10px;
        left: 10px;
