}

/* РљРЅРѕРїРєРё РґРµР№СЃС‚РІРёР№ */
.settings-actions {
    margin-top: 1.75rem;
    padding-top: 1.5rem;
    border-top: 1px solid var(--border-color);
    display: flex;
    justify-content: center;
}

.settings-reset-btn {
    padding: 0.7rem 1.6rem;
    background: var(--bg-tertiary);
    border: 1.5px solid var(--border-color);
    border-radius: 10px;
    color: var(--text-secondary);
    font-size: 0.95rem;
    font-weight: 600;
    cursor: pointer;
    transition: var(--transition);
    display: inline-flex;
    align-items: center;
}

.settings-reset-btn:hover {
    background: var(--error-color);
    color: white;
    border-color: var(--error-color);
    box-shadow: 0 4px 12px rgba(var(--error-rgb), 0.3);
}

/* РЈРІРµРґРѕРјР»РµРЅРёРµ РЅР°СЃС‚СЂРѕРµРє */
.settings-notification {
    position: fixed;
    bottom: 2rem;
    right: 2rem;
    background: linear-gradient(135deg, var(--accent-color) 0%, var(--accent-hover) 100%);
    color: white;
    padding: 1rem 1.5rem;
    border-radius: 12px;
    font-size: 1rem;
    font-weight: 600;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
    transform: translateX(400px);
    opacity: 0;
    transition: var(--transition-bounce);
    z-index: 10001;
    pointer-events: none;
    max-width: 350px;
}

.settings-notification.show {
    transform: translateX(0);
    opacity: 1;
}

/* ============================================
   РЈР РћР’РќР РђРќРРњРђР¦РР™
   ============================================ */

/* РњР°РєСЃРёРјР°Р»СЊРЅС‹Р№ СѓСЂРѕРІРµРЅСЊ (РїРѕ СѓРјРѕР»С‡Р°РЅРёСЋ - РІСЃРµ Р°РЅРёРјР°С†РёРё) */
body.animations-max {
    /* Р’СЃРµ Р°РЅРёРјР°С†РёРё РІРєР»СЋС‡РµРЅС‹ - РЅРёРєР°РєРёС… РѕРіСЂР°РЅРёС‡РµРЅРёР№ */
    --animation-state: enabled;
}

/* РЎСЂРµРґРЅРёР№ СѓСЂРѕРІРµРЅСЊ (С‚РѕР»СЊРєРѕ Р±Р°Р·РѕРІС‹Рµ РїРµСЂРµС…РѕРґС‹, Р±РµР· РґРµРєРѕСЂР°С‚РёРІРЅС‹С… Р°РЅРёРјР°С†РёР№ Рё hover-С‚СЂР°РЅСЃС„РѕСЂРјР°С†РёР№) */

/* РЈР±РёСЂР°РµРј РІСЃРµ @keyframes-Р°РЅРёРјР°С†РёРё */
body.animations-medium .page-header::before,
body.animations-medium .part-title::after,
body.animations-medium .theme-toggle::before,
body.animations-medium .task-card::before,
body.animations-medium .subject-card::before,
body.animations-medium .progress-fill::after,
body.animations-medium .ny-decorated::after {
    animation: none !important;
}

/* РЈР±РёСЂР°РµРј hover-С‚СЂР°РЅСЃС„РѕСЂРјР°С†РёРё СЃ РєРѕРЅС‚РµРЅС‚-Р±РѕРєСЃРѕРІ */
body.animations-medium .definition-box:hover,
body.animations-medium .formula-box:hover,
body.animations-medium .remark-box:hover,
body.animations-medium .experiment-box:hover,
body.animations-medium .derivation-box:hover {
    transform: none !important;
    border-width: inherit !important;
}

/* РЈР±РёСЂР°РµРј hover-С‚СЂР°РЅСЃС„РѕСЂРјР°С†РёРё СЃРѕ stat-card */
body.animations-medium .stat-card:hover {
    transform: none !important;
}

/* РЈРїСЂРѕС‰Р°РµРј hover РґР»СЏ РєР°СЂС‚РѕС‡РµРє Рё С‚РµРј вЂ” С‚РѕР»СЊРєРѕ С‚РµРЅСЊ, Р±РµР· РїРѕРґСЉС‘РјР° */
body.animations-medium .topic:hover {
    transform: none !important;
}

body.animations-medium .task-card:hover {
    transform: none !important;
}

body.animations-medium .subject-card:hover {
    transform: none !important;
}

/* РћС‚РєР»СЋС‡Р°РµРј СЃР»РѕР¶РЅС‹Рµ box-shadow РїРµСЂРµС…РѕРґС‹ РїСЂРё РЅР°РІРµРґРµРЅРёРё (С‚РѕР»СЊРєРѕ Р»С‘РіРєР°СЏ С‚РµРЅСЊ) */
body.animations-medium .topic:hover,
body.animations-medium .task-card:hover,
body.animations-medium .subject-card:hover,
body.animations-medium .definition-box:hover,
body.animations-medium .formula-box:hover,
body.animations-medium .remark-box:hover,
body.animations-medium .experiment-box:hover,
body.animations-medium .derivation-box:hover,
body.animations-medium .stat-card:hover {
    box-shadow: var(--shadow-md) !important;
}

/* Сокращаем длительность всех переходов — конкретные свойства, не all */
body.animations-medium {
    /* Переходы — те же стильные, что в «Максимальном» (это и есть «основные»
       анимации); убираем лишь пружинный «отскок» у всплывающих элементов,
       чтобы средний уровень был спокойнее, но не «другим». */
    --transition-smooth: var(--transition);
    --transition-bounce: var(--transition);
}

/* Каскадное «появление» карточек — это украшение: на среднем выключаем
   (карточки сразу на месте). animation:none безопасно сбрасывает элемент в
   видимое состояние — без вспышки и не оставляя его невидимым. */
body.animations-medium .subject-card,
body.animations-medium .grade-card,
body.animations-medium .stat-card,
body.animations-medium .task-card {
    animation: none !important;
}

/* Окна появляются спокойно — простое проявление, без масштабирования/пружины */
body.animations-medium .settings-modal:not(.hidden) .settings-modal-content,
body.animations-medium .auth-modal,
body.animations-medium .hint-modal {
    animation-name: fadeIn !important;
    animation-timing-function: var(--ease-out) !important;
}

/* РЈРїСЂРѕС‰Р°РµРј РїРµСЂРµС…РѕРґС‹ РЅР° СЌР»РµРјРµРЅС‚Р°С… вЂ” СѓР±РёСЂР°РµРј border-width, transform */
/* Переходы блоков-конспектов в среднем — те же, что в «Максимальном»
   (общая стильная кривая); отдельную «ускоренную» версию убрали, чтобы
   уровни не отличались скоростью/кривой, только набором эффектов. */

/* РЈРїСЂРѕС‰Р°РµРј hover РЅР° РєРЅРѕРїРєР°С… вЂ” Р±РµР· transform, С‚РѕР»СЊРєРѕ С†РІРµС‚/С‚РµРЅСЊ */
body.animations-medium .scroll-to-top:hover,
body.animations-medium .settings-button:hover,
body.animations-medium .menu-toggle:hover,
body.animations-medium .theme-toggle:hover,
body.animations-medium .ny-toggle:hover {
    transform: none !important;
}

/* РћС‚РєР»СЋС‡Р°РµРј РЅРѕРІРѕРіРѕРґРЅРёР№ СЃРЅРµР¶РёРЅРєР°-СЌС„С„РµРєС‚ РїСЂРё РЅР°РІРµРґРµРЅРёРё РЅР° РєР°СЂС‚РѕС‡РєРё Р·Р°РґР°С‡ */
body.animations-medium.new-year-mode .task-card:hover::after {
    content: none !important;
}

/* Р’С‹РєР»СЋС‡РµРЅРЅС‹Рµ Р°РЅРёРјР°С†РёРё */
body.animations-off *,
body.animations-off *::before,
body.animations-off *::after {
    animation: none !important;
    transition: none !important;
}

body.animations-off .task-card:hover,
body.animations-off .subject-card:hover,
body.animations-off .definition-box:hover,
body.animations-off .formula-box:hover,
body.animations-off .remark-box:hover,
body.animations-off .experiment-box:hover,
body.animations-off .derivation-box:hover,
body.animations-off .stat-card:hover,
body.animations-off .theme-toggle:hover,
body.animations-off .ny-toggle:hover,
body.animations-off .settings-button:hover,
body.animations-off .menu-toggle:hover,
body.animations-off .scroll-to-top:hover,
body.animations-off .theme-option:hover,
body.animations-off .animation-level-option:hover,
body.animations-off .task-toggle:hover,
body.animations-off .toggle-derivation:hover,
body.animations-off .hint-toggle:hover,
body.animations-off .settings-reset-btn:hover,
body.animations-off .ny-advanced-settings:hover,
body.animations-off .settings-close-btn:hover,
body.animations-off .close-sidebar:hover,
body.animations-off .auth-submit:hover,
body.animations-off .telegram-chat-button:hover,
body.animations-off .hint-save-btn:hover,
body.animations-off .retry-button:hover {
    transform: none !important;
    box-shadow: var(--shadow-sm) !important;
}

/* РћС‚РєР»СЋС‡Р°РµРј РёР·РјРµРЅРµРЅРёСЏ РїСЂРё РЅР°РІРµРґРµРЅРёРё РЅР° content-section */
body.animations-off .content-section:hover {
    transform: none !important;
}

/* РћС‚РєР»СЋС‡Р°РµРј РёР·РјРµРЅРµРЅРёСЏ РїСЂРё РЅР°РІРµРґРµРЅРёРё РЅР° topic */
body.animations-off .topic:hover {
    transform: none !important;
    box-shadow: var(--shadow-md) !important;
}

/* Р Р°Р·СЂРµС€Р°РµРј С‚РѕР»СЊРєРѕ РёР·РјРµРЅРµРЅРёРµ С†РІРµС‚Р° С„РѕРЅР° РґР»СЏ РЅР°РІРёРіР°С†РёРѕРЅРЅС‹С… СЃСЃС‹Р»РѕРє */
body.animations-off .nav-link:hover {
    transform: none !important;
    /* Р¦РІРµС‚ С„РѕРЅР° РёР·РјРµРЅСЏРµС‚СЃСЏ С‡РµСЂРµР· СЃС‚Р°РЅРґР°СЂС‚РЅС‹Рµ СЃС‚РёР»Рё */
}

/* ============================================
   СПОКОЙНОЕ ЧТЕНИЕ
   Класс no-hover теперь только не допускает hover-реакции учебных карточек
   (их правила выше уже гейтятся через body:not(.no-hover)). Универсальный
   сброс запрещён: он удалял постоянные тени, ломал transform сайдбара и
   неожиданно отключал навигацию. focus-visible всегда остаётся видимым.
   ============================================ */
body.no-hover .new-year-mode .task-card:hover::after,
body.no-hover.new-year-mode .task-card:hover::after {
    animation: none !important;
}

/* ВАЖНО: у сайдбара transform — это структурное состояние (свёрнут/открыт),
   а не hover-эффект. Универсальное правило выше обнуляло его, пока курсор над
   меню → при клике «свернуть» сайдбар оставался на месте до увода мыши.
   Возвращаем структурный transform (и плавный переход) даже при наведении. */
body.no-hover .sidebar.collapsed:hover {
    transform: translateX(-100%) !important;
    transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1) !important;
}
body.no-hover .sidebar.open:hover {
    transform: translateY(0) !important;
}

/* Внутренние переключатели доказательства относятся к тексту конспекта. */
body.no-hover .toggle-derivation:hover,
body.no-hover .toggle-proof:hover {
    opacity: 1 !important;
}
body.no-hover .theorem-box > .proof-box .toggle-proof:hover,
body.no-hover .statement-box > .proof-box .toggle-proof:hover,
body.no-hover .remark-box > .proof-box .toggle-proof:hover,
body.no-hover .corollary-box > .proof-box .toggle-proof:hover,
body.no-hover .lemma-box > .proof-box .toggle-proof:hover,
body.no-hover li > .proof-box .toggle-proof:hover {
    opacity: 0.85 !important;
}

/* Толщину бордюра НЕ нормализуем жёстко: все :hover-правила блоков теперь
   гейтятся через body:not(.no-hover) и в режиме no-hover не применяются —
   рамка остаётся базовой (2px в легаси, 1px в эксп-режиме). Прежнее
   `border-width: 2px !important` ломало эксп-режим (утолщало 1px → 2px). */

/* focus-visible ВСЕГДА должен быть виден (доступность с клавиатуры),
   даже при отключённых hover-эффектах. */
body.no-hover *:focus-visible {
    outline: 2px solid var(--accent-color);
    outline-offset: 2px;
}

/* Мобильная edge-to-edge верстка блоков: на тапе сохраняем 0/5px от спокойного состояния */
@media (max-width: 768px) {
    body.no-hover .topic > .formula-box:hover,
    body.no-hover .topic > .formula-box:active,
    body.no-hover .topic > .experiment-box:hover,
    body.no-hover .topic > .experiment-box:active,
    body.no-hover .topic > .derivation-box:hover,
    body.no-hover .topic > .derivation-box:active {
        border-width: 0 !important;
        border-left-width: 5px !important;
    }
}

/* РљРЅРѕРїРєР° РЅР°СЃС‚СЂРѕРµРє РІ СЃР°Р№РґР±Р°СЂРµ (РґР»СЏ РјРѕР±РёР»СЊРЅС‹С…) */
.settings-button-sidebar {
    display: none;
    background: var(--bg-tertiary);
    border: none;
    color: var(--text-secondary);
    width: 40px;
    height: 40px;
    border-radius: 50%;
    cursor: pointer;
    font-size: 1.3rem;
    transition: var(--transition);
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    line-height: 1;
    text-align: center;
    padding: 0;
    transform-origin: center center;
}

.settings-button-sidebar:hover {
    background: var(--border-color);
    color: var(--text-primary);
    transform: rotate(90deg);
}

.settings-button-sidebar:active {
