}

.pwa-install-help-close {
    align-items: center;
    background: var(--bg-tertiary);
    border: 0;
    border-radius: 50%;
    color: var(--text-secondary);
    cursor: pointer;
    display: inline-flex;
    font-size: 1.25rem;
    height: 2.1rem;
    justify-content: center;
    line-height: 1;
    position: absolute;
    right: 1rem;
    top: 1rem;
    width: 2.1rem;
}

.pwa-install-help-icon {
    align-items: center;
    background: rgba(var(--accent-rgb), 0.1);
    border-radius: 18px;
    display: inline-flex;
    height: 3.4rem;
    justify-content: center;
    margin-bottom: 0.95rem;
    width: 3.4rem;
}

.pwa-install-help-icon svg {
    height: 2rem;
    width: 2rem;
}

.pwa-install-help h2 {
    color: var(--text-primary);
    font-size: 1.45rem;
    line-height: 1.15;
    margin: 0 2.4rem 0.55rem 0;
}

.pwa-install-help-lead,
.pwa-install-help-note {
    color: var(--text-secondary);
    font-size: 0.92rem;
    line-height: 1.55;
    margin: 0;
}

.pwa-install-help-list {
    display: grid;
    gap: 0.65rem;
    margin: 1rem 0;
}

.pwa-install-help-list > div {
    background: var(--bg-primary);
    border: 1px solid var(--border-color);
    border-radius: 14px;
    display: grid;
    gap: 0.2rem;
    padding: 0.82rem 0.9rem;
