:root {
    --success-color: #116b32;
    --success-hover: #15803d;
    --success-rgb: 17, 107, 50;
    --warning-color: #8a4f00;
    --warning-hover: #b45309;
    --warning-rgb: 138, 79, 0;
    --error-color: #b91c1c;
    --error-hover: #b91c1c;
    --error-rgb: 185, 28, 28;
    --status-on-color: #fff;
    --info-color: var(--accent-color);
    --info-hover: var(--accent-hover);
    --text-color: var(--text-primary);
}

body.dark-theme,
body.midnight-theme,
body.experimental.exp-dark {
    --success-color: #4ade80;
    --success-hover: #86efac;
    --success-rgb: 74, 222, 128;
    --warning-color: #fbbf24;
    --warning-hover: #fcd34d;
    --warning-rgb: 251, 191, 36;
    --error-color: #f87171;
    --error-hover: #fca5a5;
    --error-rgb: 248, 113, 113;
    --status-on-color: #16161f;
    --text-color: var(--text-primary);
}

.memory-btn-remember,
.memory-stat.remember .memory-stat-value {
    --button-accent: var(--success-color);
    --button-accent-hover: var(--success-hover);
}

body :is(input, textarea)::placeholder {
    color: var(--text-secondary, var(--builder-muted, #51526b));
    opacity: 1;
}

.memory-btn-forget,
.auth-error,
.hint-delete-btn,
.bm-card-delete:hover {
    --button-accent: var(--error-color);
    --button-accent-hover: var(--error-hover);
}

.bookmark-btn.bookmarked {
    color: var(--warning-color);
}

.memory-stat.remember .memory-stat-value {
    color: var(--success-color);
}

.memory-stat.forget .memory-stat-value,
.auth-error {
    color: var(--error-color);
}
:where(
    .btn,
    .knowledge-check-btn,
    .toggle-derivation,
    .toggle-proof,
    .task-toggle,
    .auth-submit,
    .builder-btn,
    .ticket-nav-btn,
    .search-nav-btn,
    .retry-button,
    .no-results-clear,
    .settings-reset-btn,
    .ny-advanced-settings,
    .ny-settings-reset,
    .ny-settings-apply,
    .hint-save-btn,
    .hint-delete-btn,
    .hint-cancel-btn,
    .copy-block-btn
) {
    min-height: 2.4rem;
    border-radius: var(--border-radius-sm);
    font: inherit;
    font-weight: 600;
    cursor: pointer;
    transition: transform 0.2s ease,
                box-shadow 0.2s ease,
                background-color 0.2s ease,
                border-color 0.2s ease,
                color 0.2s ease,
                opacity 0.2s ease;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
}

:where(
    .btn,
    .auth-submit,
    .builder-btn-save,
    .ticket-nav-btn,
    .copy-block-btn
) {
    background: var(--button-accent, var(--accent-color));
    color: #ffffff;
    border: 1px solid var(--button-accent, var(--accent-color));
    box-shadow: var(--shadow-sm);
}

/* Hover-стили кнопок гейтятся через body:not(.no-hover) — когда пользователь
   отключает hover-эффекты, эти правила просто не применяются (гарантированно
   ноль изменений под курсором, без войны специфичностей). */
body:not(.no-hover) :where(
    .btn,
    .auth-submit,
    .builder-btn-save,
    .ticket-nav-btn,
    .copy-block-btn
):hover {
    background: var(--button-accent-hover, var(--accent-hover));
    border-color: var(--button-accent-hover, var(--accent-hover));
    box-shadow: var(--shadow-md);
}

:where(.btn-outline, .knowledge-check-btn, .hint-cancel-btn, .ny-advanced-settings) {
    background: transparent;
    color: var(--button-accent, var(--text-primary));
    border: 1.5px solid var(--button-accent, var(--border-color));
}

body:not(.no-hover) :where(.btn-outline, .knowledge-check-btn, .hint-cancel-btn, .ny-advanced-settings):hover {
    background: var(--bg-tertiary);
    color: var(--button-accent-hover, var(--text-primary));
    border-color: var(--button-accent-hover, var(--text-secondary));
}

:where(.btn-subtle, .task-toggle, .settings-reset-btn, .ny-settings-reset) {
    background: var(--bg-tertiary);
    color: var(--text-primary);
    border: 1px solid var(--border-color);
}

body:not(.no-hover) :where(.btn-subtle, .task-toggle, .settings-reset-btn, .ny-settings-reset):hover {
    background: var(--bg-primary);
    border-color: var(--text-secondary);
}

body:not(.no-hover) :where(.btn-danger, .builder-btn-reset, .hint-delete-btn):hover {
    background: var(--error-color);
    border-color: var(--error-color);
    color: var(--status-on-color, #fff);
}

:where(.btn, .btn-outline, .btn-subtle, .copy-block-btn):active {
    transform: translateY(0) scale(0.98);
}
/* =====================================================================
   НОВЫЙ ИНТЕРФЕЙС — основной дизайн сайта
   Класс body.experimental сохранён как техническое имя для совместимости.

   «Графит» — нейтральный; «Призма» — с цветными метками.
   body.exp-dark включает тёмную тему. Токены --exp-* также задают
   совместимые переменные --bg-*, --text-* для остальных страниц.
   ===================================================================== */

/* Спокойная финальная система для старого режима.
   Она сохраняет классическую ленту разделов, но убирает случайные градиенты,
   тяжёлые тени и несогласованные отступы прежней темы. */

body:not(.experimental) {
    --header-bg: var(--bg-secondary);
    --header-text: var(--text-primary);
    --border-radius: 12px;
    --border-radius-sm: 8px;
    --border-radius-lg: 16px;
    --shadow-sm: 0 1px 2px rgba(15, 23, 42, 0.045);
    --shadow-md: 0 5px 18px rgba(15, 23, 42, 0.065);
    --shadow-lg: 0 12px 32px rgba(15, 23, 42, 0.075);
    --shadow-xl: 0 18px 44px rgba(15, 23, 42, 0.09);
    line-height: 1.72;
    letter-spacing: 0;
}

body:not(.experimental):is(.dark-theme, .midnight-theme) {
    --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.22);
    --shadow-md: 0 7px 22px rgba(0, 0, 0, 0.25);
    --shadow-lg: 0 14px 38px rgba(0, 0, 0, 0.3);
