/* =========================================================
   1. БАЗА + РЕМАП ЛЕГАСИ-ПЕРЕМЕННЫХ
   ========================================================= */
body.experimental {
    /* Геометрия */
    --exp-r-sm: 8px;
    --exp-r: 12px;
    --exp-r-lg: 16px;
    --exp-r-pill: 999px;

    /* Светлые тени по умолчанию (мягкие, без «пластика») */
    --exp-shadow-sm: 0 1px 2px rgba(15, 15, 25, 0.05);
    --exp-shadow: 0 2px 8px rgba(15, 15, 25, 0.06);
    --exp-shadow-md: 0 4px 16px rgba(15, 15, 25, 0.08);
    --exp-shadow-lg: 0 12px 32px rgba(15, 15, 25, 0.10);

    /* Цветовые токены типов блоков — по умолчанию нейтральные (для «Графита») */
    --t-definition: #62626c; --t-theorem: #62626c; --t-lemma: #62626c;
    --t-statement: #62626c; --t-corollary: #62626c; --t-example: #62626c;
    --t-formula: #62626c; --t-proof: #62626c; --t-derivation: #62626c;
    --t-experiment: #62626c; --t-exercise: #62626c; --t-properties: #62626c;
    --t-system: #62626c; --t-remark: #8a6000; --t-reminder: #62626c;

    /* ---- РЕМАП легаси-переменных на --exp-* ---- */
    --bg-primary: var(--exp-bg);
    --bg-secondary: var(--exp-surface);
    --bg-tertiary: var(--exp-surface-2);
    --text-primary: var(--exp-text);
    --text-secondary: var(--exp-text-dim);
    --accent-color: var(--exp-accent);
    --accent-hover: var(--exp-accent-hover);
    --accent-rgb: var(--exp-accent-rgb);
    --primary-color: var(--exp-accent);
    --primary-gradient: linear-gradient(135deg, var(--exp-accent), var(--exp-accent-hover));
    --border-color: var(--exp-border);
    --header-bg: var(--exp-surface);
    --header-text: var(--exp-text);

    --shadow-sm: var(--exp-shadow-sm);
    --shadow-md: var(--exp-shadow);
    --shadow-lg: var(--exp-shadow-md);
    --shadow-xl: var(--exp-shadow-lg);
    --shadow-hover: var(--exp-shadow-md);

    /* Блоки — нейтральные поверхности (цвет уходит в ярлык-чип) */
    --definition-bg: var(--exp-surface); --definition-border: var(--exp-border);
    --formula-bg: var(--exp-surface); --formula-border: var(--exp-border);
    --remark-bg: var(--exp-surface); --remark-border: var(--exp-border);
    --experiment-bg: var(--exp-surface); --experiment-border: var(--exp-border);
    --derivation-bg: var(--exp-surface); --derivation-border: var(--exp-border);
    --theorem-bg: var(--exp-surface); --theorem-border: var(--exp-border);
    --lemma-bg: var(--exp-surface); --lemma-border: var(--exp-border);
    --example-bg: var(--exp-surface); --example-border: var(--exp-border);
    --statement-bg: var(--exp-surface); --statement-border: var(--exp-border);
    --corollary-bg: var(--exp-surface); --corollary-border: var(--exp-border);
    --proof-bg: var(--exp-surface); --proof-border: var(--exp-border);
    --exercise-bg: var(--exp-surface); --exercise-border: var(--exp-border);

    background-color: var(--exp-bg);
    color: var(--exp-text);
}

/* =========================================================
   2. ТОКЕНЫ РЕЖИМОВ
   ========================================================= */

/* ---- ГРАФИТ · светлая ---- */
body.experimental.exp-graphite {
    --exp-bg: #fafafa;
    --exp-surface: #ffffff;
    --exp-surface-2: #f4f4f5;
    --exp-text: #18181b;
    --exp-text-dim: #52525b;
    --exp-text-faint: #686872;
