    --exp-accent-contrast: #ffffff;
    --exp-accent-rgb: 24, 24, 27;
}

/* ---- ГРАФИТ · тёмная ---- */
body.experimental.exp-graphite.exp-dark {
    --exp-bg: #09090b;
    --exp-surface: #131316;
