/* В поддерживаемых браузерах старый и новый раздел движутся одновременно —
   без белой паузы между двумя последовательными анимациями. */
html.exp-reader-vt-active::view-transition-old(root),
html.exp-reader-vt-active::view-transition-new(root) {
    animation: none;
}

html.exp-reader-vt-next::view-transition-old(exp-reader-topic) {
    animation: expReaderVtOldNext 0.11s ease-in both;
}
html.exp-reader-vt-next::view-transition-new(exp-reader-topic) {
    animation: expReaderVtNewNext 0.17s ease-out both;
}
html.exp-reader-vt-prev::view-transition-old(exp-reader-topic) {
    animation: expReaderVtOldPrev 0.11s ease-in both;
}
html.exp-reader-vt-prev::view-transition-new(exp-reader-topic) {
    animation: expReaderVtNewPrev 0.17s ease-out both;
}

@keyframes expReaderVtOldNext {
    to { opacity: 0; transform: translate3d(-4px, 0, 0); }
}
@keyframes expReaderVtNewNext {
    from { opacity: 0; transform: translate3d(6px, 0, 0); }
}
@keyframes expReaderVtOldPrev {
    to { opacity: 0; transform: translate3d(4px, 0, 0); }
}
@keyframes expReaderVtNewPrev {
    from { opacity: 0; transform: translate3d(-6px, 0, 0); }
}

