/* Единый короткий переход между цветовыми темами. Снимки страницы
   компонуются браузером, поэтому смена не запускает сотни CSS-transition. */
html.site-theme-transition::view-transition-old(root) {
    animation: siteThemeFadeOut 0.2s cubic-bezier(0.4, 0, 1, 1) both;
}

html.site-theme-transition::view-transition-new(root) {
    animation: siteThemeFadeIn 0.24s cubic-bezier(0, 0, 0.2, 1) both;
}

@keyframes siteThemeFadeOut {
    from { opacity: 1; }
    to { opacity: 0; }
}

@keyframes siteThemeFadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
}

.site-theme-transition-veil {
    position: fixed;
    inset: 0;
    z-index: 2147483647;
    pointer-events: none;
    opacity: 1;
    transition: opacity 0.24s cubic-bezier(0, 0, 0.2, 1);
}

.site-theme-transition-veil.is-leaving {
    opacity: 0;
}

