/* =========================================================
   TYPOGRAPHY SYSTEM
   Onest keeps Cyrillic and Latin visually consistent while KaTeX
   remains responsible for mathematical notation.
   ========================================================= */

/* Onest variable — only the subsets used by the project are requested. */
@font-face {
    font-family: 'Onest';
    font-style: normal;
    font-weight: 100 900;
    font-display: swap;
    src: url("data:font/woff2;base64,") format('woff2');
    unicode-range: U+0460-052F, U+1C80-1C8A, U+20B4, U+2DE0-2DFF, U+A640-A69F, U+FE2E-FE2F;
}

@font-face {
    font-family: 'Onest';
    font-style: normal;
    font-weight: 100 900;
    font-display: swap;
    src: url("data:font/woff2;base64,") format('woff2');
    unicode-range: U+0301, U+0400-045F, U+0490-0491, U+04B0-04B1, U+2116;
}

@font-face {
    font-family: 'Onest';
    font-style: normal;
    font-weight: 100 900;
    font-display: swap;
    src: url("data:font/woff2;base64,") format('woff2');
    unicode-range: U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF,
        U+0304, U+0308, U+0329, U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF,
        U+2020, U+20A0-20AB, U+20AD-20C0, U+2113, U+2C60-2C7F, U+A720-A7FF;
}

@font-face {
    font-family: 'Onest';
    font-style: normal;
    font-weight: 100 900;
    font-display: swap;
    src: url("data:font/woff2;base64,") format('woff2');
    unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA,
        U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122,
        U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}

:root {
    --font-sans: 'Onest', 'Segoe UI Variable Text', 'Segoe UI', -apple-system,
        BlinkMacSystemFont, 'Helvetica Neue', Arial, sans-serif;
    --font-display: var(--font-sans);

    --type-caption: 0.72rem;
    --type-small: clamp(0.79rem, 0.77rem + 0.09vw, 0.86rem);
    --type-ui: clamp(0.86rem, 0.83rem + 0.12vw, 0.94rem);
    --type-body: clamp(1rem, 0.975rem + 0.11vw, 1.07rem);
    --type-lead: clamp(1.06rem, 1.01rem + 0.2vw, 1.18rem);
    --type-subheading: clamp(1.16rem, 1.07rem + 0.34vw, 1.38rem);
    --type-section: clamp(1.38rem, 1.19rem + 0.67vw, 1.78rem);
    --type-topic: clamp(1.58rem, 1.32rem + 0.92vw, 2.12rem);
    --type-page: clamp(1.9rem, 1.58rem + 1.05vw, 2.5rem);
    --type-hero: clamp(2.08rem, 1.52rem + 2.05vw, 3.45rem);

    --leading-tight: 1.08;
    --leading-heading: 1.18;
    --leading-ui: 1.42;
    --leading-body: 1.7;
    --leading-compact: 1.58;

    --tracking-display: -0.044em;
    --tracking-heading: -0.03em;
    --tracking-subheading: -0.018em;
    --tracking-body: -0.004em;
    --tracking-label: 0.085em;

    --type-measure: 46rem;
    --type-measure-wide: 50rem;
}

html {
    -webkit-text-size-adjust: 100%;
    text-size-adjust: 100%;
}

body {
    font-family: var(--font-sans);
    font-size: var(--type-body);
    font-weight: 400;
    line-height: var(--leading-body);
    letter-spacing: var(--tracking-body);
    font-kerning: normal;
    font-variant-numeric: proportional-nums;
    text-rendering: optimizeLegibility;
}

/* Experimental themes previously set their own font shorthand and therefore
   need an equally specific reset to inherit the same system. */
body.experimental {
    font-family: var(--font-sans);
    font-size: var(--type-body);
    font-weight: 400;
    line-height: var(--leading-body);
    letter-spacing: var(--tracking-body);
}

button,
input,
textarea,
select {
    font-family: var(--font-sans);
    letter-spacing: inherit;
}

:where(h1, h2, h3, h4, h5, h6) {
    font-family: var(--font-display);
    text-wrap: balance;
}

:where(p, li, dd, figcaption) {
    text-wrap: pretty;
}

/* Page-level hierarchy */
body .page-header h1 {
    font-size: var(--type-page);
