    align-items: flex-start;
    gap: 16px;
    padding: 22px;
}
body.home-page .grade-panel .subject-card .card-body { justify-content: center; }
body.home-page .home-secondary { grid-column: 2; grid-row: 1; display: grid; min-width: 0; gap: 24px; }
body.home-page .home-secondary .section-title { margin-bottom: 14px; font-size: 1rem; }
body.home-page .home-additional-grid,
body.home-page .class-section > .subjects-grid { display: grid; grid-template-columns: 1fr; gap: 10px; }
body.home-page .home-secondary .subject-card {
    min-height: 72px;
    align-items: center;
    gap: 12px;
    padding: 14px;
    border-radius: 14px !important;
}
body.home-page .home-secondary .subject-icon { width: 38px; height: 38px; border-radius: 12px; }
body.home-page .home-secondary .subject-icon svg { width: 24px; height: 24px; }
body.home-page .home-secondary .card-body { justify-content: center; }
body.home-page .home-secondary h2:not(.section-title) { font-size: 0.98rem; }
body.home-page .home-secondary .home-game-link { min-height: 48px; }
body.home-page .home-game-name { margin-left: auto; color: var(--text-secondary); font-size: 0.72rem; font-weight: 450; }
body.home-page .home-footer { margin: 32px 0 0; padding: 18px 0 0; border-top: 1px solid var(--border-color); }
body.home-page .home-footer p { display: flex; justify-content: space-between; gap: 12px; font-size: 0.75rem; letter-spacing: 0; }
body.home-page .home-footer a { color: var(--text-secondary); text-decoration: none; }

/* Only hoverable pointers get decorative feedback; keyboard focus stays explicit. */
@media (hover: hover) {
    body.home-page .subject-card:hover::before { opacity: 1; }
    body.home-page .home-controls button:hover,
    body.home-page .home-quick-customize:hover { background: var(--bg-tertiary) !important; color: var(--text-primary) !important; }
    body.home-page .home-editor-link:hover { border-color: var(--accent-color); }
}
body.home-page .subject-card:focus-visible,
body.home-page .home-controls button:focus-visible,
body.home-page .home-editor-link:focus-visible,
body.home-page .grade-tab:focus-visible,
body.home-page .home-footer a:focus-visible {
    outline: 2px solid var(--accent-color);
    outline-offset: 3px;
}

body.home-quick-dialog-open {
    overflow: hidden;
}

.home-quick-dialog[hidden] {
    display: none !important;
}

.home-quick-dialog {
    position: fixed;
    z-index: 10020;
    inset: 0;
    display: grid;
    place-items: center;
    box-sizing: border-box;
    padding: 1.25rem;
    background: color-mix(in srgb, #090b12 62%, transparent);
    backdrop-filter: blur(8px);
}

.home-quick-dialog-panel {
    width: min(860px, 100%);
    max-height: min(820px, calc(100dvh - 2.5rem));
    display: grid;
    grid-template-rows: auto minmax(0, 1fr) auto;
    overflow: hidden;
    border: 1px solid color-mix(in srgb, var(--border-color) 88%, var(--accent-color));
    border-radius: 22px;
    color: var(--text-primary);
    background: var(--bg-primary);
    box-shadow: 0 26px 80px rgba(8, 12, 24, 0.26);
    animation: home-quick-dialog-in 190ms var(--home-motion-out, ease-out) both;
}

.home-quick-dialog-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 1rem;
    padding: 1.25rem 1.35rem 1.05rem;
    border-bottom: 1px solid var(--border-color);
}

.home-quick-dialog-kicker {
    display: block;
    margin-bottom: 0.3rem;
    color: var(--accent-color);
    font-size: 0.7rem;
    font-weight: 760;
    letter-spacing: 0.08em;
    text-transform: uppercase;
}

.home-quick-dialog-header h2 {
    margin: 0;
    font-size: clamp(1.25rem, 2.5vw, 1.65rem);
    line-height: 1.2;
}

.home-quick-dialog-close {
    width: 40px;
    height: 40px;
    flex: 0 0 auto;
    display: grid;
    place-items: center;
    padding: 0;
    border: 1px solid var(--border-color);
    border-radius: 12px;
    color: var(--text-secondary);
    background: var(--bg-secondary);
    cursor: pointer;
}

.home-quick-dialog-close svg {
    width: 20px;
    height: 20px;
}

.home-quick-dialog-body {
    min-height: 0;
    overflow: auto;
    padding: 1.15rem 1.35rem 1.35rem;
    overscroll-behavior: contain;
}

.home-quick-dialog-intro {
    margin: 0 0 1.15rem;
    color: var(--text-secondary);
    font-size: 0.9rem;
    line-height: 1.5;
}

.home-quick-options {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 1.05rem 1.2rem;
}

.home-quick-option-group h3 {
    margin: 0 0 0.5rem;
    color: var(--text-secondary);
    font-size: 0.72rem;
    font-weight: 760;
    letter-spacing: 0.07em;
    text-transform: uppercase;
}

.home-quick-option-list {
    display: grid;
    gap: 0.48rem;
}

.home-quick-option {
    --quick-option-color: var(--accent-color);
    width: 100%;
    min-height: 62px;
    display: grid;
    grid-template-columns: 42px minmax(0, 1fr) 28px;
    align-items: center;
    gap: 0.72rem;
    box-sizing: border-box;
    padding: 0.58rem 0.7rem;
    border: 1px solid var(--border-color);
    border-radius: 13px;
    color: var(--text-primary);
    background: var(--bg-secondary);
    font: inherit;
    text-align: left;
    cursor: pointer;
    transition: border-color 150ms ease, background-color 150ms ease, opacity 150ms ease;
}

.home-quick-option.is-selected {
    border-color: color-mix(in srgb, var(--quick-option-color) 58%, var(--border-color));
    background: color-mix(in srgb, var(--quick-option-color) 8%, var(--bg-secondary));
}

.home-quick-option.is-limit {
    opacity: 0.5;
}

.home-quick-option-icon {
    width: 42px;
    height: 42px;
    display: grid;
    place-items: center;
    border-radius: 11px;
    color: var(--quick-option-color);
    background: color-mix(in srgb, var(--quick-option-color) 9%, var(--bg-primary));
}

.home-quick-option-icon svg {
    width: 24px;
    height: 24px;
}

.home-quick-option-copy {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 0.16rem;
}

.home-quick-option-copy strong,
.home-quick-option-copy small {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.home-quick-option-copy strong {
    font-size: 0.9rem;
    line-height: 1.22;
}

.home-quick-option-copy small {
    color: var(--text-secondary);
    font-size: 0.72rem;
}

.home-quick-option-order {
    width: 27px;
    height: 27px;
    display: grid;
    place-items: center;
    border: 1px solid var(--border-color);
    border-radius: 999px;
    color: var(--text-secondary);
    background: var(--bg-primary);
    font-size: 0.78rem;
    font-weight: 760;
}

.home-quick-option.is-selected .home-quick-option-order {
    border-color: transparent;
    color: #fff;
    background: var(--quick-option-color);
}

.home-quick-option[data-subject="physics"] { --quick-option-color: #4777a0; }
.home-quick-option[data-subject="chemistry"] { --quick-option-color: #427a67; }
.home-quick-option[data-subject="literature"] { --quick-option-color: #935f50; }
.home-quick-option[data-subject="russian"] { --quick-option-color: #a45262; }
.home-quick-option[data-subject="math"] { --quick-option-color: #9b6928; }
.home-quick-option[data-subject="geometry"] { --quick-option-color: #68609a; }
.home-quick-option[data-subject="physics-exam"] { --quick-option-color: #69668f; }
.home-quick-option[data-subject="matcenter"] { --quick-option-color: #58668e; }
.home-quick-option[data-subject="likbez"] { --quick-option-color: #735d7e; }
.home-quick-option[data-subject="english"] { --quick-option-color: #4f6f82; }
.home-quick-option[data-subject="duty"] { --quick-option-color: #4f7774; }
.home-quick-option[data-subject="tour"] { --quick-option-color: #667052; }

.home-quick-dialog-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    padding: 1rem 1.35rem;
    border-top: 1px solid var(--border-color);
    background: color-mix(in srgb, var(--bg-secondary) 74%, var(--bg-primary));
}

.home-quick-selection-meta {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 0.15rem;
}

.home-quick-selection-meta strong {
    font-size: 0.82rem;
}

.home-quick-selection-meta span {
    overflow: hidden;
    color: var(--text-secondary);
    font-size: 0.72rem;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.home-quick-selection-meta span.is-warning {
    color: var(--warning-color);
}

.home-quick-dialog-actions {
    display: flex;
    gap: 0.55rem;
}

.home-quick-cancel,
.home-quick-save {
    min-height: 42px;
    padding: 0.6rem 1rem;
    border: 1px solid var(--border-color);
    border-radius: 11px;
    font: inherit;
    font-size: 0.84rem;
    font-weight: 700;
    cursor: pointer;
}

.home-quick-cancel {
    color: var(--text-primary);
    background: var(--bg-primary);
}

.home-quick-save {
    border-color: transparent;
    color: #fff;
    background: var(--accent-color);
}

.home-quick-save:disabled {
    opacity: 0.46;
    cursor: not-allowed;
}

.home-quick-customize:focus-visible,
.home-quick-dialog button:focus-visible {
    outline: 2px solid color-mix(in srgb, var(--accent-color) 72%, white);
    outline-offset: 2px;
}

@keyframes home-quick-dialog-in {
    from { opacity: 0; transform: translateY(8px) scale(0.99); }
    to { opacity: 1; transform: translateY(0) scale(1); }
}



